namespace Monstertacle.Multisession.AgentFramework.Evidence;
/// <summary>A host-persisted association; missing association never authorizes admission.</summary>
/// <param name="EvidenceId">Evidence to renew.</param>
/// <param name="Fingerprint">Frozen definition/dependency revision.</param>
/// <param name="RequestId">Previously accepted durable request, never generated by this workflow.</param>
/// <param name="SessionId">Expected owner of that request.</param>
public sealed record EvidenceWorkItem(string EvidenceId, string Fingerprint, Guid RequestId, Guid SessionId);
